        return None;
    }
    reserve_builder_structure(DEPTH.checked_mul(std::mem::size_of::<Frame<'_>>())?).ok()?;
    let mut frames = Vec::with_capacity(DEPTH);
    if frames.capacity() != DEPTH {
        return None;
