                    module,
                    declaration,
                    alias,
                });
                Ok(())
            },
        )?;
        sorting::sort(&mut entries, remaining, |a, b, work| {
            sorting::identity(&a.declaration.stable_id, &b.declaration.stable_id, work)
        })?;
