fn visit<'a, A: Lookup<'a>>(
    caller: &Program,
    authored: &A,
    programs: &'a [Program],
    frames: &mut Vec<Frame<'a>>,
    remaining: &mut usize,
    mut found: impl FnMut(&'a str, &'a TypeDeclaration, &mut usize) -> Result<(), Vec<Diagnostic>>,
) -> Result<(), Vec<Diagnostic>> {
